/// <summary>
/// Data contract class for service <c>METSalesOrderCancelService</c>
/// </summary>
[DataContractAttribute]
public class METSalesOrderCancelContract
{
    DataAreaId  dataAreaId;
    SalesId     salesId;
    CustAccount custAccount;

    
}

Method.Source:
/// <summary>
/// Gets/sets the company ID
/// </summary>
/// <param name = "_dataAreaId">company ID</param>
/// <returns>returns the company ID</returns>
[DataMemberAttribute("@SYS181879")]
public DataAreaId parmDataAreaId(DataAreaId _dataAreaId = dataAreaId)
{
    dataAreaId = _dataAreaId;
    return dataAreaId;
}

/// <summary>
/// Gets/sets the sales order number
/// </summary>
/// <param name = "_salesId">sales order number</param>
/// <returns>return the sales order number</returns>
[DataMemberAttribute("@MET:SalesOrderNum")]
public SalesId parmSalesId(SalesId _salesId = salesId)
{
    salesId = _salesId;
    return salesId;
}

/// <summary>
/// Gets/sets the customer account number
/// </summary>
/// <param name = "_custAccount">customer account number</param>
/// <returns>returns the customer account number</returns>
[DataMemberAttribute("@MET:CustomerAccountNumber")]
public CustAccount parmCustAccount(CustAccount _custAccount = custAccount)
{
    custAccount = _custAccount;
    return custAccount;
}
